-- Generated by drizzle-kit, then made idempotent: production already has this
-- schema from the pre-Drizzle src/migrations (001 and 002), so this only records
-- the baseline there. Drizzle can't express the deferrable unique constraint.
DO $$
BEGIN
  IF to_regclass('public.films') IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'films' AND column_name = 'year'
  ) THEN
    RAISE EXCEPTION 'films predates annual watchlists; deploy the previous release first';
  END IF;
END $$;
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "films" (
	"id" text PRIMARY KEY NOT NULL,
	"title" text NOT NULL,
	"position" integer NOT NULL,
	"watched" boolean DEFAULT false NOT NULL,
	"watched_at" text,
	"created_at" text NOT NULL,
	"updated_at" text NOT NULL,
	"year" integer NOT NULL,
	CONSTRAINT "films_position_unique" UNIQUE("year","position") DEFERRABLE INITIALLY DEFERRED,
	CONSTRAINT "films_id_check" CHECK (length("id") BETWEEN 1 AND 100),
	CONSTRAINT "films_title_check" CHECK (length(trim("title")) BETWEEN 1 AND 200),
	CONSTRAINT "films_position_check" CHECK ("position" >= 0),
	CONSTRAINT "films_year_check" CHECK ("year" BETWEEN 1900 AND 9999),
	CONSTRAINT "films_watched_date" CHECK ("watched" OR "watched_at" IS NULL)
);
